"""Canonical three-phase wire contracts. Never accept identities generated by a model.

Pydantic definitions generate JSON Schema and TypeScript; versions are immutable.
Legacy preview enums are reused while that route remains backward compatible.
"""
from __future__ import annotations

from decimal import Decimal
from enum import StrEnum
from typing import Annotated, Literal
from uuid import UUID

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, HttpUrl, SecretStr, model_validator

from app.research_plan import AddOnPackage, ClarityStatus, FieldOrigin, ResearchCategory, ResearchMode

SCHEMA_VERSION = "1.0.0"
Text = Annotated[str, Field(min_length=1, max_length=10000, pattern=r"\S")]
Name = Annotated[str, Field(min_length=1, max_length=128, pattern=r"\S")]
Version = Annotated[str, Field(min_length=1, max_length=128, pattern=r"\S")]
Hash = Annotated[str, Field(pattern=r"^[0-9a-f]{64}$")]
Positive = Annotated[int, Field(gt=0, strict=True)]
Count = Annotated[int, Field(ge=0, strict=True)]
Money = Annotated[str, Field(pattern=r"^(0|[1-9][0-9]*)\.[0-9]{6}$")]


class Contract(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False, validate_default=True,
                              json_schema_serialization_defaults_required=True)


