class Versions(Contract):
    brief: Positive | None = None
    plan: Positive | None = None
    evidence_bundle: Positive | None = None
    category_catalog: Version | None = None
    source_registry: Version | None = None
    connectors: dict[Name, Version] = Field(default_factory=dict)
    prompts: dict[Name, Version] = Field(default_factory=dict)
    model: Version | None = None
    normalizer: Version | None = None
    extractor: Version | None = None
    decision_policy: Version | None = None
    validator: Version | None = None


class Envelope(Contract):
    schema_version: Literal["1.0.0"] = SCHEMA_VERSION
    user_id: UUID
    project_id: UUID
    research_id: UUID
    created_at: AwareDatetime
    versions: Versions

    def require_version_match(self, version_key: str, expected: int | str) -> None:
        recorded = getattr(self.versions, version_key)
        if recorded is not None and recorded != expected:
            raise ValueError(f"versions.{version_key} must match the record's explicit version")


class BudgetLimits(Contract):
    max_requests: Positive
    max_bytes: Positive
    max_pages: Positive
    max_records: Positive
    max_duration_seconds: Positive
    max_tokens: Positive
    max_cost_usd: Money
    soft_cost_usd: Money
    max_concurrency: Annotated[int, Field(ge=1, le=8, strict=True)]

    @model_validator(mode="after")
    def valid_cost_limits(self) -> BudgetLimits:
        if Decimal(self.soft_cost_usd) > Decimal(self.max_cost_usd):
            raise ValueError("soft_cost_usd cannot exceed max_cost_usd")
        return self


class Usage(Contract):
    requests: Count = 0
    bytes: Count = 0
    pages: Count = 0
    records: Count = 0
    duration_seconds: Annotated[float, Field(ge=0)] = 0
    input_tokens: Count = 0
    output_tokens: Count = 0
    cost_usd: Money = "0.000000"
    reserved_cost_usd: Money = "0.000000"
    provider_result_unknown: bool = False


class ProvenanceField(Contract):
    value: Text | None = None
    state: FieldState = FieldState.MISSING
    origin: FieldOrigin | None = None
    assumption_id: Name | None = None
    conflicting_values: list[Text] = Field(default_factory=list)
    prior_origins: list[FieldOrigin] = Field(default_factory=list)
    confirmed: bool = False

    @model_validator(mode="after")
    def unknowns_and_confirmation(self) -> ProvenanceField:
        if self.state == FieldState.MISSING and self.value is not None:
            raise ValueError("missing state cannot assert a value")
        if self.state in (FieldState.KNOWN, FieldState.INFERRED) and self.value is None:
            raise ValueError("known/inferred state needs a value")
        if self.state == FieldState.INFERRED and self.origin not in (FieldOrigin.AI_INFERRED, FieldOrigin.AI_HYPOTHESIS):
            raise ValueError("inferred state needs AI provenance")
        if self.state == FieldState.CONFLICTING and (self.value is not None or len(self.conflicting_values) < 2):
            raise ValueError("conflicting state keeps candidates without asserting one as fact")
        if self.state != FieldState.CONFLICTING and self.conflicting_values:
            raise ValueError("only conflicting fields contain conflicting_values")
        if self.value is None and (self.origin is not None or self.confirmed):
            raise ValueError("unknown value has no asserted origin or confirmation")
        if self.value is not None and self.origin is None:
            raise ValueError("known value needs provenance")
        if self.origin == FieldOrigin.USER_CONFIRMED and not self.confirmed:
            raise ValueError("user_confirmed origin needs confirmation")
        if self.origin in (FieldOrigin.AI_INFERRED, FieldOrigin.AI_HYPOTHESIS) and self.assumption_id is None:
            raise ValueError("AI-derived fields need a traceable assumption_id")
        return self


class BriefContent(Contract):
    original_idea: Annotated[str, Field(min_length=1, max_length=10000, pattern=r"\S")]
    normalized_idea: Text | None = None
    product_type: ProvenanceField = Field(default_factory=ProvenanceField)
    target_user: ProvenanceField = Field(default_factory=ProvenanceField)
    problem_or_job: ProvenanceField = Field(default_factory=ProvenanceField)
    context_or_niche: ProvenanceField = Field(default_factory=ProvenanceField)
    market_scope: ProvenanceField = Field(default_factory=ProvenanceField)
    business_model: ProvenanceField = Field(default_factory=ProvenanceField)
    alternatives: ProvenanceField = Field(default_factory=ProvenanceField)
    constraints: dict[Name, ProvenanceField] = Field(default_factory=dict)
    clarity_status: ClarityStatus
    missing_fields: list[Name] = Field(default_factory=list)
    clarifying_questions: Annotated[list[Text], Field(max_length=3)] = Field(default_factory=list)
    assumption_ids: list[Name] = Field(default_factory=list)
    skipped_clarification: bool = False
    continue_with_unknowns: bool = False
    language_scope: Annotated[list[Name], Field(min_length=1, max_length=8)]
    primary_category: ResearchCategory | None = None
    category_origin: FieldOrigin | None = None
    category_confirmed: bool = False
    add_on_packages: list[AddOnPackage] = Field(default_factory=list)
    secondary_categories: list[ResearchCategory] = Field(default_factory=list)
    modifiers: list[Name] = Field(default_factory=list)
    category_rationale: Text | None = None
    known_unknowns: list[Text] = Field(default_factory=list)

    @model_validator(mode="after")
    def category_and_language_consistency(self) -> BriefContent:
        if self.primary_category is None and (self.category_origin is not None or self.category_confirmed):
            raise ValueError("unmatched category has no origin or confirmation")
        if self.primary_category is not None and self.category_origin is None:
            raise ValueError("category needs provenance")
        if self.category_origin == FieldOrigin.USER_CONFIRMED and not self.category_confirmed:
            raise ValueError("user_confirmed category origin needs confirmation")
        if len(self.language_scope) != len(set(self.language_scope)) or len(self.add_on_packages) != len(set(self.add_on_packages)):
            raise ValueError("language_scope and add_on_packages must be unique")
        if self.skipped_clarification and not self.continue_with_unknowns:
            raise ValueError("skipped clarification requires an explicit continue_with_unknowns preference")
        return self


