class ResearchPlan(Envelope):
    research_plan_id: UUID
    plan_version: Positive
    plan_fingerprint: Hash
    status: Literal["draft", "awaiting_user", "confirmed"]
    brief_id: UUID
    brief_version: Positive
    brief: BriefContent
    research_mode: ResearchMode
    intents: list[ResearchIntent] = Field(default_factory=list)
    source_plan: Annotated[list[SourcePlanItem], Field(max_length=128)]
    query_plan: Annotated[list[QueryPlanItem], Field(max_length=512)]
    budget: BudgetLimits
    known_unknowns: list[Text]
    confirmed_at: AwareDatetime | None = None

    @model_validator(mode="after")
    def approved_execution_scope(self) -> ResearchPlan:
        self.require_version_match("brief", self.brief_version)
        self.require_version_match("plan", self.plan_version)
        source_ids = [s.source_id for s in self.source_plan]
        if len(source_ids) != len(set(source_ids)):
            raise ValueError("duplicate source plan identity")
        if len({q.query_id for q in self.query_plan}) != len(self.query_plan):
            raise ValueError("duplicate query identity")
        if any(q.source_id not in source_ids for q in self.query_plan):
            raise ValueError("query must reference a planned source")
        intent_ids = {i.intent_id for i in self.intents if i.included}
        if len({i.intent_id for i in self.intents}) != len(self.intents):
            raise ValueError("duplicate research intent identity")
        if any(q.intent_id not in intent_ids for q in self.query_plan):
            raise ValueError("query must reference an included research intent")
        sources = {s.source_id: s for s in self.source_plan}
        intents = {i.intent_id: i for i in self.intents}
        for source in self.source_plan:
            if source.limits.max_requests > self.budget.max_requests or source.limits.max_total_bytes > self.budget.max_bytes or source.limits.max_pages > self.budget.max_pages or source.limits.max_items > self.budget.max_records or source.limits.max_seconds > self.budget.max_duration_seconds or source.limits.max_llm_tokens > self.budget.max_tokens:
                raise ValueError("source limits cannot exceed run budget")
        for query in self.query_plan:
            source = sources[query.source_id]
            if query.intent != intents[query.intent_id].intent:
                raise ValueError("query intent must match its referenced intent")
            if query.surface_id != source.surface_id or query.intent not in source.supported_intents:
                raise ValueError("query must use the planned surface and supported intent")
            if query.language not in self.brief.language_scope or query.language not in source.language_scope:
                raise ValueError("query language must match brief and source scope")
            for key in SourceLimits.model_fields:
                if getattr(query.limits, key) > getattr(source.limits, key):
                    raise ValueError("query limits cannot exceed source profile limits")
        if (self.status == "confirmed") != (self.confirmed_at is not None):
            raise ValueError("confirmed status and timestamp must agree")
        if self.status == "confirmed":
            if any(s.permission != PermissionStatus.PERMITTED or s.health not in (SourceHealth.SUPPORTED, SourceHealth.QUALIFIED) for s in self.source_plan):
                raise ValueError("confirmed plan cannot execute an unqualified or unpermitted source")
            if self.brief.clarity_status == ClarityStatus.NEEDS_CLARIFICATION:
                raise ValueError("unresolved clarification cannot execute")
            if self.brief.primary_category is None or not self.brief.category_confirmed:
                raise ValueError("confirmed plan needs a confirmed matched category")
            values = [getattr(self.brief, name) for name in ("product_type", "target_user", "problem_or_job", "context_or_niche", "market_scope", "business_model", "alternatives")]
            values.extend(self.brief.constraints.values())
            if any(v.origin == FieldOrigin.AI_HYPOTHESIS and not v.confirmed for v in values):
                raise ValueError("unconfirmed hypothesis cannot seed scope")
            if any(q.origin == FieldOrigin.AI_HYPOTHESIS and not q.user_confirmed for q in self.query_plan):
                raise ValueError("unconfirmed query hypothesis cannot execute")
        return self


class SourceCounts(Contract):
    discovered: Count = 0
    fetched: Count = 0
    normalized: Count = 0
    eligible: Count = 0
    unique: Count = 0
    independent: Count = 0
    claims: Count = 0

    @model_validator(mode="after")
    def ordered_counts(self) -> SourceCounts:
        if not self.discovered >= self.fetched >= self.normalized >= self.eligible >= self.unique >= self.independent:
            raise ValueError("counts must follow discovered/fetched/normalized/eligible/unique/independent order")
        return self


