    query_id: UUID | None = None
    details_ref: Name | None = None
    source_id: Name | None = None
    retryable: bool = False
    retry_after_seconds: Count | None = None
    usage: Usage | None = None
    remaining_work: list[Text] = Field(default_factory=list)
    next_step: Text | None = None


