class RawArtifact(Envelope):
    artifact_id: UUID
    execution_id: UUID
    query_id: UUID
    source_id: Name
    source_url: HttpUrl
    fetched_url: HttpUrl | None = None
    collected_at: AwareDatetime
    published_at: AwareDatetime | None = None
    archive_captured_at: AwareDatetime | None = None
    license_or_restriction: Text | None = None
    research_plan_version: Positive
    access_method: AccessMethod
    artifact_origin: Literal["live_capture", "archive_copy"]
    content_kind: ContentKind
    status: SourceStatus
    body_ref: Annotated[str, Field(min_length=1, max_length=512)] | None = None
    content_hash: Hash | None = None
    byte_count: Count
    media_type: Name | None = None
    connector_version: Version
    fields: dict[Name, Text | None] = Field(default_factory=dict)
    error: ApiError | None = None

    @model_validator(mode="after")
    def inspectable_content(self) -> RawArtifact:
        self.require_version_match("plan", self.research_plan_version)
        connector = self.versions.connectors.get(self.source_id)
        if connector is not None and connector != self.connector_version:
            raise ValueError("connector version must match source version snapshot")
        if self.access_method == AccessMethod.ARCHIVE and self.artifact_origin != "archive_copy":
            raise ValueError("archive capture must retain archive provenance")
        if self.status == SourceStatus.SUCCEEDED and self.content_kind == ContentKind.FETCHED_CONTENT:
            if self.body_ref is None or self.content_hash is None or self.byte_count == 0:
                raise ValueError("successful fetched content needs inspectable bytes and hash")
        return self


class TextSegment(Envelope):
    segment_id: UUID
    document_id: UUID
    segment_type: Literal["body", "title", "review", "comment", "quote", "other"]
    text: Annotated[str, Field(min_length=1, max_length=2000000)]
    start_offset: Count
    end_offset: Positive
    text_hash: Hash
    normalized_content_hash: Hash
    source_locator: Name | None = None
    normalization_version: Version

    @model_validator(mode="after")
    def valid_span(self) -> TextSegment:
        self.require_version_match("normalizer", self.normalization_version)
        if self.end_offset - self.start_offset != len(self.text):
            raise ValueError("segment offsets use Unicode code points and must span the text")
        return self


class NormalizedDocument(Envelope):
    document_id: UUID
    artifact_id: UUID
    external_id: Name | None = None
    document_type: Literal["article", "review", "comment", "api_record", "official_page", "other"]
    title: Text | None = None
    body_original_ref: Text
    canonical_url: HttpUrl | None = None
    parent_document_id: UUID | None = None
    author_reference: Name | None = None
    collected_at: AwareDatetime
    updated_at: AwareDatetime | None = None
    locale: Name | None = None
    engagement_metadata: dict[Name, int | str | None] = Field(default_factory=dict)
    supersedes_document_id: UUID | None = None
    document_version: Positive
    status: Literal["normalized", "rejected"]
    normalized_text: Annotated[str, Field(max_length=2000000)]
    normalized_content_hash: Hash
    normalization_version: Version
    language: Name | None
    published_at: AwareDatetime | None
    source_url: HttpUrl
    segments: list[TextSegment]
    exact_duplicate_of: UUID | None = None
    near_duplicate_of: UUID | None = None
    independent_identity_key: Name | None = None
    ownership_key: Name | None = None
    quality_flags: list[Name] = Field(default_factory=list)

    @model_validator(mode="after")
    def segment_lineage(self) -> NormalizedDocument:
        self.require_version_match("normalizer", self.normalization_version)
        ids = [s.segment_id for s in self.segments]
        if len(ids) != len(set(ids)):
            raise ValueError("duplicate segment identity")
        for s in self.segments:
            if (s.user_id, s.project_id, s.research_id, s.document_id) != (self.user_id, self.project_id, self.research_id, self.document_id):
                raise ValueError("segment lineage must match its document")
            if s.normalization_version != self.normalization_version or s.normalized_content_hash != self.normalized_content_hash or self.normalized_text[s.start_offset:s.end_offset] != s.text:
                raise ValueError("segment text/version must match the full normalized text")
        return self


