    source_id: Name
    verbatim_quote: Annotated[str, Field(min_length=1, max_length=10000)]
    start_offset: Count
    end_offset: Positive
    segment_text_hash: Hash
    normalized_content_hash: Hash
    normalization_version: Version
    source_url: HttpUrl
    collected_at: AwareDatetime
    published_at: AwareDatetime | None = None
    validation_status: ValidationStatus
    validated_at: AwareDatetime | None = None
    rejection_reason: Text | None = None

    @model_validator(mode="after")
    def quote_span_and_validation(self) -> Citation:
        self.require_version_match("normalizer", self.normalization_version)
        if len(self.claim_ids) != len(set(self.claim_ids)):
            raise ValueError("duplicate citation claim binding")
        if self.end_offset - self.start_offset != len(self.verbatim_quote):
            raise ValueError("quote offsets must span the exact Unicode quote")
        if self.validation_status == ValidationStatus.VALIDATED and self.validated_at is None:
            raise ValueError("validated citation needs validation timestamp")
        if self.validation_status == ValidationStatus.REJECTED and self.rejection_reason is None:
            raise ValueError("rejected citation needs a reason")
        return self


