class EvidenceBundle(Envelope):
    bundle_id: UUID
    bundle_version: Positive
    status: Literal["complete", "partial", "insufficient"]
    source_reports: list[SourceReport]
    claims: list[Claim]
    citations: list[Citation]
    coverage: dict[SearchIntent, list[Name]]
    coverage_assessments: list[CoverageAssessment] = Field(default_factory=list)
    independence: list[IndependenceGroup] = Field(default_factory=list)
    relations: list[DocumentRelation] = Field(default_factory=list)
    evidence_maps: EvidenceMaps = Field(default_factory=EvidenceMaps)
    selection_trace_ref: Text | None = None
    source_registry_version: Version
    parent_bundle_id: UUID | None = None
    gap_ids: list[UUID] = Field(default_factory=list)
    duplicate_document_ids: list[UUID]
    known_unknowns: list[Text]
    limitations: list[Text]
    usage: Usage

    @model_validator(mode="after")
    def evidence_bindings(self) -> EvidenceBundle:
        self.require_version_match("evidence_bundle", self.bundle_version)
        claims = {c.claim_id: c for c in self.claims}
        citations = {c.citation_id: c for c in self.citations}
        if len(claims) != len(self.claims) or len(citations) != len(self.citations):
            raise ValueError("duplicate evidence identity")
        if len({report.source_report_id for report in self.source_reports}) != len(self.source_reports):
            raise ValueError("duplicate source report identity")
        for record in [*self.source_reports, *self.claims, *self.citations]:
            if (record.user_id, record.project_id, record.research_id) != (self.user_id, self.project_id, self.research_id):
                raise ValueError("bundle cannot contain foreign evidence")
        for claim in self.claims:
            if claim.validation_status != ValidationStatus.VALIDATED:
                raise ValueError("bundle claims must be validated")
            if any(cid not in citations or claim.claim_id not in citations[cid].claim_ids for cid in claim.citation_ids):
                raise ValueError("claim citation bindings must be bidirectional")
        for citation in self.citations:
            if citation.validation_status != ValidationStatus.VALIDATED:
                raise ValueError("bundle citations must be validated")
            if any(cid not in claims or citation.citation_id not in claims[cid].citation_ids for cid in citation.claim_ids):
                raise ValueError("citation claim bindings must be bidirectional")
        for report in self.source_reports:
            if any(cid not in claims for cid in report.claim_ids) or any(cid not in citations for cid in report.citation_ids):
                raise ValueError("source report cannot reference absent evidence")
            if any(citations[cid].source_id != report.source_id for cid in report.citation_ids):
                raise ValueError("source report citations must belong to its source")
            if any(not set(claims[cid].citation_ids).intersection(report.citation_ids) for cid in report.claim_ids):
                raise ValueError("source report claims need a citation from that source report")
            if any(cid not in report.claim_ids for cid in [*report.supporting_claim_ids, *report.opposing_claim_ids]):
                raise ValueError("source report directions must reference its claims")
            if any(claims[cid].direction != Direction.SUPPORTS for cid in report.supporting_claim_ids) or any(claims[cid].direction != Direction.OPPOSES for cid in report.opposing_claim_ids):
                raise ValueError("source report direction must match its actual claim")
        for group in self.independence:
            if any(cid not in claims for cid in group.claim_ids):
                raise ValueError("independence group cannot reference absent claims")
        entries = [entry for key in ("problems", "voice_of_customer", "competitors", "pricing", "opportunity_hypotheses") for entry in getattr(self.evidence_maps, key)]
        if any(cid not in claims for entry in entries for cid in entry.claim_ids):
            raise ValueError("evidence maps cannot reference absent claims")
        if any(cid not in claims for cid in self.evidence_maps.market_maturity_claim_ids):
            raise ValueError("market maturity cannot reference absent claims")
        return self


