class DecisionReport(Envelope):
    report_id: UUID
    report_version: Positive
    previous_report_id: UUID | None = None
    bundle_id: UUID
    bundle_version: Positive
    outcome: Outcome
    status: Literal["published"]
    management_review_required: Literal[True] = True
    market_assessment: list[ReportStatement]
    summary: list[ReportStatement]
    rationale: list[RationaleBlock]
    counter_evidence: list[ReportStatement]
    known_unknowns: list[Text]
    limitations: list[Text]
    sufficiency: SufficiencyAssessment
    gap_ids: list[UUID]
    pillar_profiles: list[PillarProfile]
    target_customer: list[ReportStatement]
    problem: list[ReportStatement]
    competitors: list[ReportStatement]
    opportunity_hypotheses: list[ReportStatement]
    supporting_claim_ids: list[UUID]
    opposing_claim_ids: list[UUID]
    citation_ids: list[UUID]
    critical_unknowns: list[Text]
    assumptions: list[Text]
    execution_constraints: list[Text]
    user_conditions_snapshot: dict[Name, ProvenanceField]
    primary_validation: PrimaryValidation
    decision_stability: DecisionStability
    next_actions: list[NextAction]
    modification: Modification | None
    investigation: Investigation | None
    usage: Usage
    validation: ReportValidation
    errors: list[ApiError]

    @model_validator(mode="after")
    def eligible_outcome(self) -> DecisionReport:
        self.require_version_match("evidence_bundle", self.bundle_version)
        self.require_version_match("decision_policy", self.sufficiency.policy_version)
        self.require_version_match("validator", self.validation.validator_version)
        if self.outcome not in self.sufficiency.eligible_outcomes:
            raise ValueError("outcome must be permitted by deterministic sufficiency policy")
        if self.sufficiency.status == "insufficient" and self.outcome != Outcome.INVESTIGATE_MORE:
            raise ValueError("insufficient evidence cannot publish a definitive assessment")
        if (self.outcome == Outcome.MODIFY) != (self.modification is not None):
            raise ValueError("modification must exist exactly for Modify outcome")
        if (self.outcome == Outcome.INVESTIGATE_MORE) != (self.investigation is not None):
            raise ValueError("investigation must exist exactly for Investigate More outcome")
        if self.investigation and set(self.investigation.gap_ids) != set(self.gap_ids):
            raise ValueError("investigation must reference this report's gaps")
        return self


