    def execution_lineage_and_versions(self) -> ResearchRun:
        self.require_version_match("brief", self.brief_version)
        self.require_version_match("plan", self.plan_version)
        if len({e.execution_id for e in self.source_executions}) != len(self.source_executions):
            raise ValueError("duplicate source execution identity")
        for execution in self.source_executions:
            if (execution.user_id, execution.project_id, execution.research_id) != (self.user_id, self.project_id, self.research_id):
                raise ValueError("run cannot contain foreign source execution")
            if execution.versions.plan is not None and execution.versions.plan != self.plan_version:
                raise ValueError("source execution must retain the run plan version")
        return self


